create or replace function mask_phone(value text)
returns text
language sql
immutable
as $$
  select case
    when value is null or length(regexp_replace(value, ''\D'', '''', ''g'')) < 6 then null
    else ''+***'' || right(regexp_replace(value, ''\D'', '''', ''g''), 4)
  end;
$$;

